<script>
  import {onDestroy,createEventDispatcher} from 'svelte';
  import {lookupCoinGecko,coinGeckoCandidates} from '$lib/asset-catalog/coingecko.js';
  export let backend; export let fundId=null;
  let context,customIds=[],canPublish=false,publish=false,epoch=0,active=true,networks=[],tokens=[],canManage=false,loading=false,busy=false,error='',success='',search='',network='',coinId='',candidates=[],editing=null;
  const dispatch=createEventDispatcher();
  const blank=()=>({assetKey:'',name:'',symbol:'',network:'ethereum',standard:'erc20',contract:'',decimals:18,source:'',verified:false,enabled:true});
  let draft=blank(),showForm=false;
  onDestroy(()=>{active=false;epoch++;});
  $: if(backend&&(context?.actor!==backend||context?.fund!==fundId)){context={actor:backend,fund:fundId};void load();}
  $: filtered=tokens.filter(t=>(!network||t.network===network)&&`${t.name} ${t.symbol} ${t.contract} ${t.assetKey}`.toLowerCase().includes(search.toLowerCase()));
  function unwrap(r){if('err'in r)throw new Error(r.err);return r.ok;}
  async function load(){const version=++epoch;loading=true;error='';showForm=false;canManage=false;canPublish=false;tokens=[];customIds=[];try{const data=fundId===null?await backend.getGlobalAssetCatalog():unwrap(await backend.getFundAssetCatalog(fundId));if(active&&version===epoch){({networks,tokens,canManage}=data);customIds=data.customIds??[];canPublish=data.canPublish??canManage;}}catch(e){if(active&&version===epoch)error=e.message||'Unable to load catalog';}finally{if(active&&version===epoch)loading=false;}}
  function edit(t=null){editing=t;publish=t?!customIds.includes(t.id):fundId===null;draft=t?{assetKey:t.assetKey,name:t.name,symbol:t.symbol,network:t.network,standard:t.standard,contract:t.contract,decimals:Number(t.decimals),source:t.source,verified:t.verified,enabled:t.enabled}:blank();showForm=true;}
  async function save(){if(!draft.assetKey.trim())draft.assetKey=`custom:${crypto.randomUUID()}`;busy=true;error='';const version=epoch;try{const args=[editing?[editing.id]:[],editing?.revision??0n,{...draft,decimals:Number(draft.decimals),verified:publish&&draft.verified}];unwrap(await (publish?backend.saveGlobalAsset(...args):backend.saveFundCustomAsset(fundId,...args)));if(!active||epoch!==version)return;showForm=false;await load();success=publish?'Global asset saved':'Custom asset saved for this Fund';}catch(e){if(active&&version===epoch)error=e.message;}finally{busy=false;}}
  async function lookup(){busy=true;error='';candidates=[];const version=epoch;try{const result=await lookupCoinGecko(coinId.trim());if(active&&version===epoch){candidates=result;if(!result.length)error='No supported token entries with known precision. Add native coins manually or check the source metadata.';}}catch(e){if(active&&version===epoch)error=e.message;}finally{busy=false;}}
  async function file(event){error='';candidates=[];try{const f=event.target.files?.[0];if(!f)return;if(f.size>2000000)throw new Error('JSON file is too large');candidates=coinGeckoCandidates(JSON.parse(await f.text()));if(!candidates.length)throw new Error('No supported token entries with known precision');}catch(e){error=e.message;}event.target.value='';}
  async function use(t){busy=true;error='';const version=epoch;try{unwrap(await backend.importGlobalAsset(fundId,t.id));if(!active||epoch!==version)return;success='Asset added to this Fund. Choose it when adding a holding.';dispatch('imported');}catch(e){if(active&&version===epoch)error=e.message;}finally{busy=false;}}
</script>
<section class="rounded-2xl bg-white p-5 text-slate-950">
  <div class="flex flex-wrap justify-between gap-3"><div><h2 class="text-xl font-semibold">{fundId===null?'Global asset catalog':'Asset catalog & custom definitions'}</h2><p class="mt-1 text-sm text-slate-600">Choose a shared definition, create your own, or optionally import CoinGecko metadata. Fund custom definitions stay within this Fund.</p></div><button disabled={loading||busy} on:click={load}>Refresh catalog</button></div>
  {#if error}<p role="alert" class="mt-3 rounded bg-rose-50 p-3 text-rose-800">{error}</p>{/if}{#if success}<p role="status" class="mt-3 text-emerald-700">{success}</p>{/if}
  <div class="my-4 flex flex-wrap gap-3"><label>Search<input bind:value={search} placeholder="Name, symbol or contract"/></label><label>Network<select bind:value={network}><option value="">All networks</option>{#each networks as n}<option value={n.id}>{n.name}</option>{/each}</select></label>{#if canManage}<button on:click={()=>edit()}>+ Add definition</button>{/if}</div>
  {#if canManage}<div class="mb-5 rounded-xl bg-slate-50 p-4"><h3 class="font-semibold">Import from CoinGecko</h3><div class="mt-3 flex flex-wrap items-end gap-3"><label>CoinGecko ID<input bind:value={coinId} placeholder="usd-coin"/></label><button disabled={busy} on:click={lookup}>Look up</button><label>Or import coin JSON<input type="file" accept=".json,application/json" on:change={file}/></label></div><p class="mt-2 text-xs text-slate-600">Public API access may be limited. API keys stay outside the browser. Native coins and missing precision require manual entry.</p>{#each candidates as c}<div class="mt-3 break-all text-sm">{c.name} · {c.network} · {c.contract} · {c.decimals} decimals <button on:click={()=>{edit();draft={...c};}}>Review & add</button></div>{/each}<a class="mt-3 inline-block text-sm underline" href="https://www.coingecko.com/en/api" target="_blank" rel="noreferrer">Data provided by CoinGecko</a></div>{/if}
  {#if showForm&&canManage}<form class="my-5 border-y py-4" on:submit|preventDefault={save}><h3 class="font-semibold">{editing?'Edit definition':'Add definition'}</h3><fieldset disabled={busy} class="mt-3 grid min-w-0 gap-3 sm:grid-cols-2">{#if canPublish&&fundId!==null&&!editing}<label><input type="checkbox" bind:checked={publish}/> Publish to global catalog</label>{/if}<label>Asset family (optional)<input maxlength="80" placeholder="Groups versions of the same asset across networks" disabled={!!editing} bind:value={draft.assetKey}/></label><label>Name<input required maxlength="120" bind:value={draft.name}/></label><label>Symbol<input required maxlength="24" bind:value={draft.symbol}/></label><label>Network<select disabled={!!editing} bind:value={draft.network}>{#each networks as n}<option value={n.id}>{n.name}</option>{/each}</select></label><label>Standard<select disabled={!!editing} bind:value={draft.standard}>{#each ['native','erc20','icrc1','icrc2','spl','spl2022'] as s}<option value={s}>{s}</option>{/each}</select></label><label>Contract / mint / ledger<input disabled={!!editing} bind:value={draft.contract} required={draft.standard!=='native'} maxlength="200"/></label><label>Decimals<input type="number" min="0" max="18" required disabled={!!editing} bind:value={draft.decimals}/></label><label>Source<input maxlength="500" required={draft.verified} bind:value={draft.source}/></label>{#if publish&&canPublish}<label><input type="checkbox" bind:checked={draft.verified}/> Reviewed by administrator</label>{/if}<label><input type="checkbox" bind:checked={draft.enabled}/> Enabled</label><button type="submit">Save definition</button><button type="button" on:click={()=>showForm=false}>Cancel</button></fieldset></form>{/if}
  {#if loading}<p>Loading catalog…</p>{:else}<div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Asset</th><th>Network</th><th>Contract / identifier</th><th>Decimals</th><th>Status</th><th>Actions</th></tr></thead><tbody>{#each filtered as t (t.id)}<tr class="border-t"><td>{t.name}<br/><span class="text-slate-500">{t.symbol}</span></td><td>{t.network}</td><td class="max-w-xs break-all">{t.contract||'Native asset'}</td><td>{t.decimals}</td><td>{customIds.includes(t.id)?'Fund custom':'Global'} · {t.enabled?'Enabled':'Disabled'} · {t.verified?'Reviewed':'Unverified'}</td><td>{#if fundId!==null&&t.enabled&&canManage}<button disabled={busy} on:click={()=>use(t)}>Add to Fund</button>{/if}{#if canManage&&(customIds.includes(t.id)||canPublish)}<button disabled={busy} on:click={()=>edit(t)}>Edit</button>{/if}</td></tr>{:else}<tr><td colspan="6" class="py-5 text-slate-500">No matching definitions. Add a custom definition or optionally import from CoinGecko.</td></tr>{/each}</tbody></table></div>{/if}
</section>
<style>input:not([type=checkbox]),select{display:block;width:100%;border:1px solid #cbd5e1;border-radius:.5rem;padding:.5rem;margin-top:.25rem}button{border:1px solid #cbd5e1;border-radius:.5rem;padding:.5rem .75rem;background:white}button:disabled{opacity:.5}label{font-size:.875rem;min-width:0}td,th{padding:.75rem .5rem}button:hover:not(:disabled){background:#f1f5f9}</style>
